/*
 * Native executable coverage audit.
 * Compares executable ELF sections with native ranges represented by C sidecars.
 * Uncovered gaps are explicit frontier rows, not reconstructed code.
 */
#include <stdint.h>

typedef struct VMNativeExecSectionCoverage {
    const char *section;
    uint64_t start;
    uint64_t stop;
    uint64_t bytes;
    uint64_t covered_bytes;
    uint64_t uncovered_bytes;
    uint32_t coverage_x100;
    uint32_t range_count;
    uint32_t merged_range_count;
} VMNativeExecSectionCoverage;

typedef struct VMNativeRecoveredRange {
    const char *section;
    uint64_t start;
    uint64_t stop;
    uint64_t bytes;
    const char *source;
    const char *detail;
} VMNativeRecoveredRange;

typedef struct VMNativeExecutableGap {
    const char *section;
    uint64_t start;
    uint64_t stop;
    uint64_t bytes;
} VMNativeExecutableGap;

